import { u } from 'unist-builder';
import { visitParents } from 'unist-util-visit-parents';
const isInsideTile = (ancestors) => ancestors.some((ancestor) => typeof ancestor === 'object' &&
    ancestor !== null &&
    'name' in ancestor &&
    ancestor.name === 'Tile');
export const rehypeZoomImages = () => (tree) => {
    visitParents(tree, ['mdxJsxFlowElement', 'mdxJsxTextElement'], (node, ancestors) => {
        if (node.type !== 'mdxJsxFlowElement' && node.type !== 'mdxJsxTextElement')
            return;
        if (node.name !== 'img' &&
            node.name !== 'picture' &&
            node.name !== 'figure' &&
            node.name !== 'iframe') {
            return;
        }
        const parent = ancestors[ancestors.length - 1];
        if (!parent || !('children' in parent))
            return;
        const index = parent.children.indexOf(node);
        if (index === -1)
            return;
        const noZoom = node.attributes.find((attr) => attr.type === 'mdxJsxAttribute' && attr.name === 'noZoom');
        const shouldSkipZoom = noZoom || isInsideTile(ancestors);
        if (shouldSkipZoom)
            return;
        if (node.name === 'iframe') {
            if (node.type !== 'mdxJsxFlowElement')
                return;
            parent.children.splice(index, 1, u('mdxJsxFlowElement', { name: 'OptimizedFrame', attributes: node.attributes }, []));
            return;
        }
        // For img elements, replace with OptimizedImage (it applies Zoom internally)
        if (node.name === 'img') {
            const optimizedImg = u(node.type, {
                name: 'OptimizedImage',
                attributes: node.attributes,
            }, []);
            parent.children.splice(index, 1, optimizedImg);
            return;
        }
        parent.children.splice(index, 1, u('element', {
            tagName: 'ZoomImage',
            properties: {},
        }, [node]));
    });
};
